package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching products by various fields
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")
	userFilter := r.URL.Query().Get("filter")

	// Build base query
	query := "SELECT id, name, price, category, stock_count FROM products WHERE 1=1"

	if category != "" {
		// Parameterized - safe
		query += " AND category = $1"
	} else {
		query += " AND category IS NOT NULL"
	}

	if minPrice != "" {
		query += fmt.Sprintf(" AND price >= %s", sanitizeNumeric(minPrice))
	}

	// Advanced filter - allows power users to specify additional WHERE conditions
	// This is intentionally flexible for internal tooling use
	if userFilter != "" {
		// Basic blocklist check
		lower := strings.ToLower(userFilter)
		if strings.Contains(lower, "drop") || strings.Contains(lower, "truncate") ||
			strings.Contains(lower, "delete") || strings.Contains(lower, "update") ||
			strings.Contains(lower, "insert") || strings.Contains(lower, "alter") {
			http.Error(w, "Invalid filter", 400)
			return
		}
		query += " AND " + userFilter
	}

	// Sort handling
	allowedSorts := map[string]bool{"name": true, "price": true, "category": true}
	if sortField != "" && allowedSorts[sortField] {
		query += " ORDER BY " + sortField
	} else {
		query += " ORDER BY name"
	}

	query += " LIMIT 100"

	var rows *sql.Rows
	var err error
	if category != "" {
		rows, err = db.Query(query, category)
	} else {
		rows, err = db.Query(query)
	}
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, cat string
		var price float64
		var stock int
		if err := rows.Scan(&id, &name, &price, &cat, &stock); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(`  {"id":%d,"name":"%s","price":%.2f,"category":"%s","stock":%d}`, id, name, price, cat, stock)))
		first = false
	}
	w.Write([]byte("\n]"))
}

func sanitizeNumeric(s string) string {
	var result strings.Builder
	for _, c := range s {
		if (c >= '0' && c <= '9') || c == '.' {
			result.WriteRune(c)
		}
	}
	if result.Len() == 0 {
		return "0"
	}
	return result.String()
}

func main() {
	http.HandleFunc("/api/products/search", searchHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
